<?php declare(strict_types=1); namespace Tests;
use App\Integrations\Tmdb\{TmdbClient,TmdbException,TmdbMediaDetailsNormalizer,TmdbSeasonDetailsNormalizer}; use PHPUnit\Framework\TestCase;
final class TmdbSeasonTest extends TestCase {
 public function testSeriesSummariesIncludeSeasonZeroAndIgnoreInvalidItems():void{$d=(new TmdbMediaDetailsNormalizer())->series(['id'=>1396,'name'=>'Breaking Bad','seasons'=>[['id'=>1,'season_number'=>1,'name'=>'Temporada 1','episode_count'=>7,'air_date'=>'2008-01-20','poster_path'=>'/s1.jpg'],['id'=>2,'season_number'=>0,'name'=>'Especiais','episode_count'=>3],['id'=>0,'season_number'=>2,'name'=>'Inválida','episode_count'=>4]]]);self::assertNotNull($d);self::assertSame([1,0],array_map(fn($s)=>$s->seasonNumber,$d->seasons));self::assertSame(7,$d->seasons[0]->episodeCount);$m=(new TmdbMediaDetailsNormalizer())->movie(['id'=>1,'title'=>'Movie','seasons'=>[['id'=>1,'season_number'=>1,'name'=>'No','episode_count'=>1]]]);self::assertSame([],$m?->seasons);}
 public function testSeasonDetailsNormalizeEpisodesAndIgnoreMalformedOnes():void{$x=(new TmdbSeasonDetailsNormalizer())->normalize(['id'=>3572,'season_number'=>1,'name'=>'Temporada 1','overview'=>'Resumo','air_date'=>'2008-01-20','poster_path'=>'/s.jpg','episodes'=>[['id'=>62085,'season_number'=>1,'episode_number'=>1,'name'=>'Piloto','air_date'=>'2008-01-20','runtime'=>58,'still_path'=>'/e.jpg'],['id'=>2,'season_number'=>1,'episode_number'=>0,'name'=>'Inválido'],['id'=>3,'season_number'=>2,'episode_number'=>2,'name'=>'Outra temporada']]],1396);self::assertNotNull($x);self::assertCount(1,$x->episodes);self::assertSame('Piloto',$x->episodes[0]->name);self::assertSame(58,$x->episodes[0]->runtime);self::assertNull((new TmdbSeasonDetailsNormalizer())->normalize(['season_number'=>1],1396));}
 public function testClientUsesRestrictedSeasonPathLanguageOnlyAndSupportsZero():void{$urls=[];$c=new TmdbClient('token',http:static function(string$url)use(&$urls){$urls[]=$url;$n=str_contains($url,'season/0')?0:1;return['status'=>200,'body'=>json_encode(['id'=>10,'season_number'=>$n,'name'=>$n===0?'Especiais':'Temporada 1','episodes'=>[]])];});self::assertSame(1,$c->seasonDetails(1396,1)->seasonNumber);self::assertSame(0,$c->seasonDetails(1396,0)->seasonNumber);self::assertSame('https://api.themoviedb.org/3/tv/1396/season/1?language=pt-BR',$urls[0]);self::assertStringNotContainsString('region=',implode(' ',$urls));self::assertStringNotContainsString('append_to_response',implode(' ',$urls));}
 public function testSeasonRejectsInvalidIdentifiersAndMapsErrors():void{$called=false;$c=new TmdbClient('token',http:static function()use(&$called){$called=true;return['status'=>200,'body'=>'{}'];});foreach([[0,1],[1,-1],[2147483648,1],[1,2147483648]]as[$i,$s]){try{$c->seasonDetails($i,$s);self::fail();}catch(\InvalidArgumentException){}}self::assertFalse($called);$nf=new TmdbClient('token',http:static fn()=>['status'=>404,'body'=>'{}']);try{$nf->seasonDetails(1396,1);self::fail();}catch(TmdbException$e){self::assertSame('not_found',$e->category);}}
}
